INSERT INTO vocabulary_generation_job (
    job_uid, card_uid, base_revision_uid, template_key, template_version, theme_uid, theme_version,
    status, attempt_count, request_json, result_revision_uid, error_code,
    error_message, generation_outcome, warning, available_at, started_at, lease_token, lease_expires_at, finished_at
) VALUES (
    #{jobUid}, #{cardUid}, #{baseRevisionUid}, #{templateKey}, #{templateVersion}, #{themeUid}, #{themeVersion},
    #{status}, #{attemptCount}, #{requestJson}, #{resultRevisionUid}, #{errorCode},
    #{errorMessage}, #{generationOutcome}, #{warning}, #{availableAt}, #{startedAt}, #{leaseToken}, #{leaseExpiresAt}, #{finishedAt}
