mapper.select:
SELECT job.id, job.job_uid, job.card_uid, job.base_revision_uid, job.template_key, job.template_version, job.theme_uid, job.theme_version, job.status, job.attempt_count, job.request_json, job.result_revision_uid, job.error_code, job.error_message, job.generation_outcome, job.warning, job.available_at, job.started_at, job.lease_token, job.lease_expires_at, job.finished_at, job.created_at, job.updated_at FROM vocabulary_generation_job job INNER JOIN ( SELECT candidate.card_uid, MAX(candidate.id) AS latest_id FROM vocabulary_generation_job candidate INNER JOIN vocabulary_card card ON card.card_uid = candidate.card_uid AND card.user_id = #{userId} AND card.deleted_at IS NULL WHERE candidate.card_uid IN
#{cardUid}
GROUP BY candidate.card_uid ) latest ON latest.latest_id = job.id ORDER BY job.card_uid
